// В функции navigate добавьте поддержку секций
const navigate = (page, params = {}) => {
  setCurrentPage(page);
  setPageParams(params);
  window.location.hash = page + (params.id ? `/${params.id}` : '') + (params.section ? `#${params.section}` : '');
};

// В рендере передавайте section
const renderPage = () => {
  switch (currentPage) {
    case 'catalog':
      return <Catalog onNavigate={navigate} />;
    case 'product':
      return <ProductPage onNavigate={navigate} />;
    case 'profile':
      return <Profile onNavigate={navigate} />;
    case 'auth':
      return <Auth onNavigate={navigate} />;
    case 'about':
      return <About onNavigate={navigate} />;
    default:
      return <Home onNavigate={navigate} section={pageParams.section} />;
  }
};
